export type Rgb = readonly [number, number, number];

export const clamp01 = (t: number) => Math.min(1, Math.max(0, t));

/** A point as fractions of the canvas box: `[0.5, 0.5]` is the centre. */
export type Anchor = readonly [number, number];

export const mix = (a: Rgb, b: Rgb, t: number): Rgb => [
	a[0] + (b[0] - a[0]) * t,
	a[1] + (b[1] - a[1]) * t,
	a[2] + (b[2] - a[2]) * t,
];

export function hex(value: string): Rgb {
	const n = Number.parseInt(value.replace("#", ""), 16);
	return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

/** What every effect takes for a colour: `"#e5343a"` or `[229, 52, 58]`. */
export type RgbInput = Rgb | string;

export const toRgb = (value: RgbInput): Rgb =>
	typeof value === "string" ? hex(value) : value;

/** Straight RGBA packed as an ImageData Uint32 view holds it. */
export const rgba = (r: number, g: number, b: number, a: number) =>
	((a << 24) | (b << 16) | (g << 8) | r) >>> 0;

/** Source-over of `color` at `alpha` onto `px[i]`. Shared by every painter. */
export function blendOver(px: Uint32Array, i: number, [r, g, b]: Rgb, alpha: number) {
	const d = px[i];
	const da = (d >>> 24) / 255;
	const sa = clamp01(alpha);
	if (da === 0) {
		px[i] = rgba(r, g, b, Math.round(sa * 255));
		return;
	}
	const oa = sa + da * (1 - sa);
	const w = sa / oa;
	px[i] = rgba(
		r * w + (d & 255) * (1 - w),
		g * w + ((d >>> 8) & 255) * (1 - w),
		b * w + ((d >>> 16) & 255) * (1 - w),
		Math.round(oa * 255),
	);
}

/**
 * mulberry32 (Tommy Ettinger, public domain): a seeded stream, so an effect
 * replays identically for a given seed rather than drifting between reloads.
 */
export function seededRandom(seed: number): () => number {
	let s = seed >>> 0;
	return () => {
		s = (s + 0x6d2b79f5) >>> 0;
		let t = Math.imul(s ^ (s >>> 15), 1 | s);
		t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
		return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
	};
}

/**
 * The grid an effect paints into. Every effect draws through these four calls
 * and nothing else, which is what lets one effect run on any renderer: the
 * dither renderer turns them into Bayer-thresholded pixels, another could turn
 * them into glyphs. Writes outside the grid are dropped.
 */
export interface Surface {
	readonly cols: number;
	readonly rows: number;
	clear(): void;
	/** A solid cell, source-over onto whatever is already there. */
	blend(x: number, y: number, color: Rgb, alpha: number): void;
	/** A field sample at `density` 0–1: heat, glow, a fading band. */
	dither(x: number, y: number, density: number, color: Rgb, gain?: number): void;
	/** A sparkle: the centre cell plus four arms that flare in at `arms` 0–1. */
	glint(x: number, y: number, color: Rgb, alpha: number, arms?: number): void;
}

export interface FxFrame {
	px: Surface;
	cols: number;
	rows: number;
	/** Seconds since the engine started. */
	t: number;
	/** Seconds since the previous frame, capped so a background tab can't jump. */
	dt: number;
	/** Eased 0–1 activation, driven by `setActive`. */
	intensity: number;
	reduced: boolean;
	rand: () => number;
}

export interface FxEffect<O = unknown> {
	resize(cols: number, rows: number, rand: () => number): void;
	/** Advance and paint. Return true when the surface holds a new frame. */
	step(frame: FxFrame): boolean;
	/** True once nothing is left to animate at the current intensity. */
	idle(): boolean;
	/**
	 * Apply changed options without a restart. Only the keys present have
	 * changed, and a key present but undefined goes back to its default. The
	 * effect decides what each change costs: most apply on the next frame, and
	 * one that sizes the simulation rebuilds just that part.
	 */
	set(options: O): void;
}

/** An effect's factory: `fire`, `rings`, and so on. */
export type FxFactory<O> = (options?: O) => FxEffect<O>;

/**
 * Merges `patch` over `current` key by key, sending a key that is present but
 * undefined back to its default. What an effect's `set` builds its options
 * with, so removing a prop behaves like never having passed it.
 */
export function assign<T extends object>(defaults: T, current: T, patch: Partial<T>): T {
	const next = { ...current };
	for (const key of Object.keys(patch) as (keyof T)[]) {
		next[key] = (patch[key] ?? defaults[key]) as T[keyof T];
	}
	return next;
}

/**
 * A running effect and the way to change it. A renderer runs `effect` and
 * subscribes, so `set` repaints even when the frame loop has parked: under
 * reduced motion, or after an ease-out.
 */
export interface Fx<O = unknown> {
	readonly effect: FxEffect<O>;
	/** Change options in place, without a re-render or a restart. */
	set(options: O): void;
	subscribe(listener: () => void): () => void;
}

/** Builds an effect and wraps it in an `Fx`. In React, `useFx` does this for you. */
export function createFx<O>(factory: FxFactory<O>, options?: O): Fx<O> {
	const effect = factory(options);
	const listeners = new Set<() => void>();
	return {
		effect,
		set(next) {
			effect.set(next);
			for (const listener of listeners) listener();
		},
		subscribe(listener) {
			listeners.add(listener);
			return () => listeners.delete(listener);
		},
	};
}

/** What a renderer hands the engine: somewhere to paint, and a way to show it. */
export interface Renderer {
	/**
	 * Fit the backing store to a CSS box. Returns the new surface, or null when
	 * the grid is unchanged and the effect should keep its state.
	 */
	resize(width: number, height: number): Surface | null;
	/** Put the surface's current contents on screen. */
	present(): void;
}

/**
 * Runs one effect against one renderer: eases `intensity` toward its target
 * and steps the effect on requestAnimationFrame only while something is
 * changing and the canvas is on screen. An idle or off-screen effect costs
 * nothing.
 */
export class FxEngine {
	private surface: Surface | null = null;
	private effect: FxEffect;
	private unsubscribe: () => void;
	private readonly rand: () => number;
	private raf = 0;
	private last = 0;
	private t = 0;
	private intensity = 0;
	private target = 0;
	private reduced = false;
	private hidden = false;

	constructor(
		private readonly renderer: Renderer,
		fx: Fx,
		{ seed = 1 }: { seed?: number } = {},
	) {
		this.rand = seededRandom(seed);
		this.effect = fx.effect;
		this.unsubscribe = fx.subscribe(this.wake);
	}

	resize(width: number, height: number) {
		const surface = this.renderer.resize(width, height);
		if (!surface) return;
		this.surface = surface;
		this.effect.resize(surface.cols, surface.rows, this.rand);
		this.wake();
	}

	setActive(on: boolean) {
		this.target = on ? 1 : 0;
		this.wake();
	}

	setReduced(reduced: boolean) {
		this.reduced = reduced;
		this.wake();
	}

	/**
	 * Pauses the loop while the canvas is off screen, and picks up where it
	 * left off when it comes back. Changes made meanwhile (`setActive`, `set`,
	 * a resize) are kept and applied then.
	 */
	setVisible(visible: boolean) {
		this.hidden = !visible;
		if (visible) {
			this.wake();
		} else if (this.raf) {
			cancelAnimationFrame(this.raf);
			this.raf = 0;
		}
	}

	setFx(fx: Fx) {
		this.unsubscribe();
		this.unsubscribe = fx.subscribe(this.wake);
		this.effect = fx.effect;
		if (this.surface) this.effect.resize(this.surface.cols, this.surface.rows, this.rand);
		this.wake();
	}

	destroy() {
		this.unsubscribe();
		if (this.raf) cancelAnimationFrame(this.raf);
		this.raf = 0;
	}

	private readonly wake = () => {
		if (this.raf || this.hidden) return;
		this.last = 0;
		this.raf = requestAnimationFrame(this.tick);
	};

	private readonly tick = (now: number) => {
		this.raf = 0;
		const px = this.surface;
		if (!px) return;
		const dt = this.last ? Math.min((now - this.last) / 1000, 0.1) : 1 / 60;
		this.last = now;
		this.t += dt;

		const ease = 1 - Math.exp(-dt * (this.reduced ? 30 : 8));
		this.intensity += (this.target - this.intensity) * ease;
		if (Math.abs(this.target - this.intensity) < 0.002) this.intensity = this.target;

		const painted = this.effect.step({
			px,
			cols: px.cols,
			rows: px.rows,
			t: this.t,
			dt,
			intensity: this.intensity,
			reduced: this.reduced,
			rand: this.rand,
		});
		if (painted) this.renderer.present();

		const settled = this.intensity === this.target;
		if (settled && this.effect.idle() && (this.target === 0 || this.reduced)) return;
		this.raf = requestAnimationFrame(this.tick);
	};
}

export interface Particle {
	x: number;
	y: number;
	vx: number;
	vy: number;
	age: number;
	life: number;
	phase: number;
}

/** 0–1 wink: a slow sine per particle, offset by its own phase. */
export const twinkle = (t: number, phase: number, hz = 1.6) =>
	(Math.sin(t * hz * Math.PI * 2 + phase) + 1) / 2;

/** Arms flare only across the top of the wink, so the plus is a flash, not a shape. */
export const arms = (tw: number) => Math.max(0, (tw - 0.8) * 5);

import { useEffect, useRef, useState } from "react";
import { createFx, type Fx, type FxFactory } from "./engine";

const same = (a: unknown, b: unknown): boolean =>
	Object.is(a, b) ||
	(Array.isArray(a) &&
		Array.isArray(b) &&
		a.length === b.length &&
		a.every((v, i) => same(v, b[i])));

/**
 * Builds an effect once and keeps it in step with `options`, render by render,
 * without restarting it: pass options as plain props, inline arrays and all.
 * Hand the result to any renderer's canvas. For something that changes every
 * frame, such as a pointer position, call `fx.set` from the handler instead of
 * re-rendering.
 *
 * A different `factory` builds a new effect, which starts from scratch.
 */
export function useFx<O>(factory: FxFactory<O>, options?: NoInfer<O>): Fx<O> {
	const [built, setBuilt] = useState(() => ({ factory, fx: createFx(factory, options) }));
	let { fx } = built;
	if (built.factory !== factory) {
		fx = createFx(factory, options);
		setBuilt({ factory, fx });
	}

	const last = useRef({ fx, options });
	// Every render, after commit: only the keys whose values changed reach the
	// effect, so an unchanged inline `colors` array costs nothing, and a value
	// set through `fx.set` holds until its prop changes. A new effect was built
	// with these options, so it is compared against them, not the old one's.
	useEffect(() => {
		const seen = last.current.fx === fx ? last.current.options : options;
		const prev = (seen ?? {}) as Record<string, unknown>;
		const next = (options ?? {}) as Record<string, unknown>;
		last.current = { fx, options };
		const patch: Record<string, unknown> = {};
		let changed = false;
		for (const key of new Set([...Object.keys(prev), ...Object.keys(next)])) {
			if (same(prev[key], next[key])) continue;
			patch[key] = next[key];
			changed = true;
		}
		if (changed) fx.set(patch as O);
	});

	return fx;
}

import { type DependencyList, useEffect, useRef } from "react";
import { type Fx, FxEngine, type Renderer } from "./engine";

export interface FxEngineOptions {
	effect: Fx;
	active: boolean;
	reduced: boolean;
	seed: number;
}

/**
 * What every renderer's canvas shares: builds an engine around `create`'s
 * renderer, sizes it to the wrapper, pauses it off screen, and keeps
 * `effect`, `active` and `reduced` in step without rebuilding. Only `seed`
 * and `deps`, what the renderer is built from, rebuild it.
 */
export function useFxEngine<R extends Renderer>(
	create: (canvas: HTMLCanvasElement) => R,
	{ effect, active, reduced, seed }: FxEngineOptions,
	deps: DependencyList,
) {
	const wrapRef = useRef<HTMLDivElement>(null);
	const canvasRef = useRef<HTMLCanvasElement>(null);
	const engineRef = useRef<FxEngine | null>(null);
	const rendererRef = useRef<R | null>(null);
	const runningRef = useRef(effect);

	// biome-ignore lint/correctness/useExhaustiveDependencies: the rest apply in place below
	useEffect(() => {
		const wrap = wrapRef.current;
		const canvas = canvasRef.current;
		if (!wrap || !canvas) return;
		const renderer = create(canvas);
		const engine = new FxEngine(renderer, effect, { seed });
		rendererRef.current = renderer;
		engineRef.current = engine;
		runningRef.current = effect;
		engine.setReduced(reduced);
		engine.setActive(active);
		// Fires once on observe, which sizes the first frame.
		const ro = new ResizeObserver(([entry]) => {
			const { width, height } = entry.contentRect;
			engine.resize(width, height);
		});
		ro.observe(wrap);
		// The margin starts a canvas just before it scrolls in.
		const io = new IntersectionObserver(
			([entry]) => engine.setVisible(entry.isIntersecting),
			{ rootMargin: "100px" },
		);
		io.observe(wrap);
		return () => {
			ro.disconnect();
			io.disconnect();
			engine.destroy();
			engineRef.current = null;
			rendererRef.current = null;
		};
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [seed, ...deps]);

	useEffect(() => {
		if (runningRef.current === effect) return;
		runningRef.current = effect;
		engineRef.current?.setFx(effect);
	}, [effect]);

	useEffect(() => {
		engineRef.current?.setReduced(reduced);
	}, [reduced]);

	useEffect(() => {
		engineRef.current?.setActive(active);
	}, [active]);

	return { wrapRef, canvasRef, engineRef, rendererRef };
}
